    } catch (error) {
      if (mounted) _showMessage(_message(error));
    }
  }

  InventoryLocation? _warehouseLocationFor(String warehouseId) {
    for (final location in _warehouseLocations) {
      if (location.warehouseId == warehouseId) {
        return location;
      }
